-- supabase/add-legal-pages-i18n.sql
--
-- Run this ONCE in the Supabase SQL Editor to add the text for the new
-- Privacy Policy and Returns & Exchanges pages, the consent-checkbox
-- text, and two new footer links. Safe to re-run: only ADDS these
-- specific keys, never touches anything you've already edited.

update site_data
set value = jsonb_set(
  jsonb_set(
    value,
    '{en}',
    (value->'en') || '{"privacy_eyebrow": "Legal", "privacy_title": "Privacy Policy", "privacy_subtitle": "How MESIR collects, uses, and protects your personal data.", "privacy_updated": "This policy is effective from the date of publication and applies to all visitors of mesirfragrance.com.", "privacy_collect_title": "1. What information we collect", "privacy_collect_text": "When you send an order request from the cart or use the contact form, we collect the information you provide: your name, phone number, Telegram username, and/or email address, along with the message or list of products you''re interested in. We do not collect payment card details — orders are confirmed and paid for directly with our team, not through this website.", "privacy_use_title": "2. How we use it", "privacy_use_text": "We use this information solely to respond to your inquiry, confirm your order, and arrange delivery or pickup. We do not use it for automated marketing, and we do not sell or rent your data to third parties.", "privacy_share_title": "3. Who we share it with", "privacy_share_text": "Order and contact requests are delivered to our team via Telegram''s messaging platform. Product and site content is hosted with Supabase, our database provider. Neither service is authorized to use your data for its own purposes — they act only as our technical infrastructure providers.", "privacy_retention_title": "4. How long we keep it", "privacy_retention_text": "We retain order and contact information for as long as needed to fulfill your request and to meet our accounting and legal obligations, after which it is deleted. You may request earlier deletion at any time — see your rights below.", "privacy_rights_title": "5. Your rights", "privacy_rights_text": "Under the Law of the Republic of Armenia \"On Protection of Personal Data\", you have the right to access the personal data we hold about you, request its correction or deletion, and withdraw your consent to its processing at any time. To exercise any of these rights, contact us using the details below.", "privacy_contact_title": "6. Contact us", "privacy_contact_text": "For any question about this policy or your personal data, email us at hello@mesirfragrance.com.", "order_consent_text": "I agree to the processing of my personal data as described in the <a href=\"privacy.html\" target=\"_blank\">Privacy Policy</a>.", "footer_returns": "Returns & Exchanges", "footer_privacy": "Privacy Policy", "returns_eyebrow": "Customer Care", "returns_title": "Returns & Exchanges", "returns_subtitle": "Our policy for returning or exchanging an order.", "returns_period_title": "1. Return period", "returns_period_text": "You may request a return or exchange within 14 days of receiving your order. To start a return, contact us using the details below — we''ll confirm the next steps with you directly.", "returns_condition_title": "2. Condition of the item", "returns_condition_text": "For hygiene reasons, opened or used perfume and home fragrance products cannot be returned or exchanged unless the item arrived damaged or is not what you ordered. Unopened items in their original packaging are eligible for return within the period above.", "returns_howto_title": "3. How to request a return", "returns_howto_text": "Message us on Telegram or by email with your order details and the reason for the return. We''ll let you know whether the item qualifies and, if so, arrange collection or ask you to send it back.", "returns_refund_title": "4. Refunds", "returns_refund_text": "Once we''ve received and checked the returned item, we''ll process your refund using the same method you paid with, or arrange an exchange if you prefer. Refunds are typically completed within a few business days of the item reaching us.", "returns_damaged_title": "5. Damaged or incorrect items", "returns_damaged_text": "If your order arrives damaged or you received the wrong item, contact us as soon as possible with a photo — we''ll cover the cost of return shipping and send a replacement or full refund.", "returns_contact_title": "6. Contact us", "returns_contact_text": "For any return or exchange request, email us at hello@mesirfragrance.com or message us on Telegram."}'::jsonb
  ),
  '{ru}',
  (value->'ru') || '{"privacy_eyebrow": "Правовая информация", "privacy_title": "Политика конфиденциальности", "privacy_subtitle": "Как MESIR собирает, использует и защищает ваши персональные данные.", "privacy_updated": "Настоящая политика действует с момента публикации и распространяется на всех посетителей mesirfragrance.com.", "privacy_collect_title": "1. Какие данные мы собираем", "privacy_collect_text": "Когда вы отправляете заявку из корзины или пишете через форму контактов, мы получаем указанные вами данные: имя, номер телефона, имя пользователя в Telegram и/или email, а также сообщение или список интересующих товаров. Мы не собираем данные банковских карт — заказ подтверждается и оплачивается напрямую с нашей командой, а не через сайт.", "privacy_use_title": "2. Как мы их используем", "privacy_use_text": "Мы используем эти данные исключительно для ответа на ваш запрос, подтверждения заказа и организации доставки или самовывоза. Мы не используем их для автоматической рассылки рекламы и не передаём и не продаём их третьим лицам.", "privacy_share_title": "3. С кем мы делимся данными", "privacy_share_text": "Заявки и сообщения из формы контактов доставляются нашей команде через Telegram. Товары и контент сайта хранятся у Supabase, нашего провайдера базы данных. Ни один из этих сервисов не вправе использовать ваши данные в собственных целях — они выступают только как техническая инфраструктура.", "privacy_retention_title": "4. Как долго мы храним данные", "privacy_retention_text": "Мы храним данные заявок и обращений столько, сколько необходимо для выполнения вашего запроса и соблюдения бухгалтерских и юридических обязательств, после чего они удаляются. Вы можете запросить более раннее удаление в любой момент — см. ваши права ниже.", "privacy_rights_title": "5. Ваши права", "privacy_rights_text": "В соответствии с Законом Республики Армения «О защите персональных данных» вы имеете право получить доступ к своим персональным данным, которые мы храним, запросить их исправление или удаление, а также в любой момент отозвать согласие на их обработку. Чтобы воспользоваться любым из этих прав, свяжитесь с нами по контактам ниже.", "privacy_contact_title": "6. Связаться с нами", "privacy_contact_text": "По любым вопросам об этой политике или ваших персональных данных пишите на hello@mesirfragrance.com.", "order_consent_text": "Я согласен(на) на обработку моих персональных данных в соответствии с <a href=\"privacy.html\" target=\"_blank\">Политикой конфиденциальности</a>.", "footer_returns": "Возврат и обмен", "footer_privacy": "Политика конфиденциальности", "returns_eyebrow": "Забота о клиентах", "returns_title": "Возврат и обмен", "returns_subtitle": "Наши условия возврата или обмена заказа.", "returns_period_title": "1. Срок возврата", "returns_period_text": "Вы можете запросить возврат или обмен в течение 14 дней с момента получения заказа. Чтобы начать возврат, свяжитесь с нами по контактам ниже — мы подскажем дальнейшие шаги.", "returns_condition_title": "2. Состояние товара", "returns_condition_text": "По гигиеническим причинам вскрытые или использованные парфюмерия и ароматизаторы для дома не подлежат возврату или обмену, за исключением случаев, когда товар пришёл повреждённым или не соответствует заказу. Невскрытые товары в оригинальной упаковке подлежат возврату в указанный выше срок.", "returns_howto_title": "3. Как оформить возврат", "returns_howto_text": "Напишите нам в Telegram или на email с указанием номера заказа и причины возврата. Мы сообщим, подходит ли товар под условия возврата, и организуем забор товара или попросим отправить его нам.", "returns_refund_title": "4. Возврат средств", "returns_refund_text": "После получения и проверки возвращённого товара мы вернём средства тем же способом, которым была произведена оплата, либо оформим обмен по вашему желанию. Обычно возврат средств занимает несколько рабочих дней с момента получения нами товара.", "returns_damaged_title": "5. Повреждённые или неверные товары", "returns_damaged_text": "Если заказ пришёл повреждённым или вам прислали не тот товар — свяжитесь с нами как можно скорее и приложите фото. Мы возьмём на себя расходы на обратную доставку и вышлем замену или вернём деньги полностью.", "returns_contact_title": "6. Связаться с нами", "returns_contact_text": "По любым вопросам возврата или обмена пишите на hello@mesirfragrance.com или в Telegram."}'::jsonb
)
where key = 'i18n';
